mapper.select:
SELECT id,adjustment_id,plan_id,serial_id,sku_id,operation_id,kind,from_epoch,state,claim_epoch,attempts FROM count_serial_intent
WHERE enterprise_id=#{e} AND warehouse_id=#{w} AND plan_id=#{plan} AND state IN ('PENDING','RUNNING') AND next_attempt_at<=#{now}
ORDER BY next_attempt_at,id LIMIT 1 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE count_serial_intent s SET state='PENDING',attempts=0,claim_epoch=claim_epoch+1,next_attempt_at=#{now},last_error=NULL,version=version+1,updated_at=#{now}
WHERE s.enterprise_id=#{e} AND s.warehouse_id=#{w} AND s.id=#{id} AND s.claim_epoch=#{epoch} AND s.state='ISOLATED'
  AND EXISTS(SELECT 1 FROM count_adjustment_intent a WHERE a.enterprise_id=s.enterprise_id AND a.warehouse_id=s.warehouse_id AND a.id=s.adjustment_id AND a.state='PENDING')
